internal abstract class GUPPricingAttributeAbstractProvider implements GUPIPricingAttributeProvider
{

}

Method.Source:
// Attribute with Fixed-list == Yes. 
public Set getAllowedValues(GUPIPricingAttribute _attribute)
{
    var ret = new Set(Types::String);
    GUPPricingAttributeEcoResAttribute attr = _attribute;

    EcoResAttributeType attributeType;
    EcoResEnumerationAttributeTypeValue enumerationAttributeTypeValue;
    EcoResValue value;

    str attributeToSearch = attr.getAttributeType();

    if (attr.getDataType() == AttributeDataType::Reference)
    {
        EcoResAttribute ecoResAttribute;
        EcoResAttribute localEcoResAttribute;
        EcoResAttributeType localEcoResAttributeType;
        EcoResReferenceValue ecoResReferenceValue;
        EcoResValue referencedValue;
        EcoResAttributeDefaultValue ecoResAttributeDefaultValue;

        select * from ecoResAttribute where ecoResAttribute.Name == attr.getName();

        select firstOnly localEcoResAttribute
            join localEcoResAttributeType
            where localEcoResAttributeType.RecId ==  localEcoResAttribute.AttributeType
            join ecoResReferenceValue
                where ecoResReferenceValue.RefRecId == localEcoResAttribute.RecId
                   && ecoResReferenceValue.RefTableId == localEcoResAttribute.TableId
            join ecoResAttributeDefaultValue
                where ecoResAttributeDefaultValue.Attribute == ecoResAttribute.RecId
                   && ecoResAttributeDefaultValue.Value == ecoResReferenceValue.RecId
            ;

        attributeToSearch = localEcoResAttribute.Name;

    }

    while select attributeType
    where attributeType.Name == attributeToSearch
    join enumerationAttributeTypeValue
    where enumerationAttributeTypeValue.AttributeType == attributeType.RecId
    join * from value
    where value.RecId == enumerationAttributeTypeValue.Value
    {
        if ((value as EcoResTextValue).textValue)
        {
            ret.add(any2Str((value as EcoResTextValue).textValue));
        }
        else if ((value as EcoResIntValue).intValue)
        {
            ret.add(any2Str((value as EcoResIntValue).intValue));
        }
    }


    return ret;
}

abstract public Query buildPricingObjectQuery(Query _query, GUPIPricingAttribute _pricingAttr, anytype _value, Map _qbdsMap = null)
{
}

protected AttributeDataType getAttributeType(str _pricingAttrName)
{
    EcoResAttribute attr;

    select firstonly attr where attr.Name == _pricingAttrName;

    return attr.getActualDataType();
}
